17	package org.springframework.boot.context.config;
18	
19	import java.io.IOException;
20	import java.util.ArrayList;
21	import java.util.Collections;
22	import java.util.HashSet;
23	import java.util.LinkedHashMap;
24	import java.util.List;
25	import java.util.Map;
26	import java.util.Set;
27	
28	import org.apache.commons.logging.Log;
29	import org.jspecify.annotations.Nullable;
30	
31	import org.springframework.boot.logging.DeferredLogFactory;
32	import org.springframework.core.log.LogMessage;
33	
34	/**
35	 * Imports {@link ConfigData} by {@link ConfigDataLocationResolver resolving} and
36	 * {@link ConfigDataLoader loading} locations. {@link ConfigDataResource resources} are
37	 * tracked to ensure that they are not imported multiple times.
38	 *
39	 * @author Phillip Webb
40	 * @author Madhura Bhave
41	 */
42	class ConfigDataImporter {
43	
44		private final Log logger;
45	
46		private final ConfigDataLocationResolvers resolvers;
47	
48		private final ConfigDataLoaders loaders;
49	
50		private final ConfigDataNotFoundAction notFoundAction;
51	
52		private final Set<ConfigDataResource> loaded = new HashSet<>();
53	
54		private final Set<ConfigDataLocation> loadedLocations = new HashSet<>();
55	
56		private final Set<ConfigDataLocation> optionalLocations = new HashSet<>();
57	
58		/**
59		 * Create a new {@link ConfigDataImporter} instance.
60		 * @param logFactory the log factory
61		 * @param notFoundAction the action to take when a location cannot be found
62		 * @param resolvers the config data location resolvers
63		 * @param loaders the config data loaders
64		 */
65		ConfigDataImporter(DeferredLogFactory logFactory, ConfigDataNotFoundAction notFoundAction,
66				ConfigDataLocationResolvers resolvers, ConfigDataLoaders loaders) {
67			this.logger = logFactory.getLog(getClass());
68			this.resolvers = resolvers;
69			this.loaders = loaders;
70			this.notFoundAction = notFoundAction;
71		}
72	
73		/**
74		 * Resolve and load the given list of locations, filtering any that have been
75		 * previously loaded.
76		 * @param activationContext the activation context
77		 * @param locationResolverContext the location resolver context
78		 * @param loaderContext the loader context
79		 * @param locations the locations to resolve
80		 * @return a map of the loaded locations and data
81		 */
82		Map<ConfigDataResolutionResult, ConfigData> resolveAndLoad(@Nullable ConfigDataActivationContext activationContext,
83				ConfigDataLocationResolverContext locationResolverContext, ConfigDataLoaderContext loaderContext,
84				List<ConfigDataLocation> locations) {
85			try {
86				Profiles profiles = (activationContext != null) ? activationContext.getProfiles() : null;
87				List<ConfigDataResolutionResult> resolved = resolve(locationResolverContext, profiles, locations);
88				return load(loaderContext, resolved);
89			}
90			catch (IOException ex) {
91				throw new IllegalStateException("IO error on loading imports from " + locations, ex);
92			}
93		}
94	
95		private List<ConfigDataResolutionResult> resolve(ConfigDataLocationResolverContext locationResolverContext,
96				@Nullable Profiles profiles, List<ConfigDataLocation> locations) {
97			List<ConfigDataResolutionResult> resolved = new ArrayList<>(locations.size());
98			for (ConfigDataLocation location : locations) {
99				resolved.addAll(resolve(locationResolverContext, profiles, location));
100			}
101			return Collections.unmodifiableList(resolved);
102		}
103	
104		private List<ConfigDataResolutionResult> resolve(ConfigDataLocationResolverContext locationResolverContext,
105				@Nullable Profiles profiles, ConfigDataLocation location) {
106			try {
107				return this.resolvers.resolve(locationResolverContext, location, profiles);
108			}
109			catch (ConfigDataNotFoundException ex) {
110				handle(ex, location, null);
111				return Collections.emptyList();
112			}
113		}
114	
115		private Map<ConfigDataResolutionResult, ConfigData> load(ConfigDataLoaderContext loaderContext,
116				List<ConfigDataResolutionResult> candidates) throws IOException {
117			Map<ConfigDataResolutionResult, ConfigData> result = new LinkedHashMap<>();
118			for (int i = candidates.size() - 1; i >= 0; i--) {
119				ConfigDataResolutionResult candidate = candidates.get(i);
120				ConfigDataLocation location = candidate.getLocation();
121				ConfigDataResource resource = candidate.getResource();
122				this.logger.trace(LogMessage.format("Considering resource %s from location %s", resource, location));
123				if (resource.isOptional()) {
124					this.optionalLocations.add(location);
125				}
126				if (this.loaded.contains(resource)) {
127					this.logger
128						.trace(LogMessage.format("Already loaded resource %s ignoring location %s", resource, location));
129					this.loadedLocations.add(location);
130				}
131				else {
132					try {
133						ConfigData loaded = this.loaders.load(loaderContext, resource);
134						if (loaded != null) {
135							this.logger.trace(LogMessage.format("Loaded resource %s from location %s", resource, location));
136							this.loaded.add(resource);
137							this.loadedLocations.add(location);
138							result.put(candidate, loaded);
139						}
140					}
141					catch (ConfigDataNotFoundException ex) {
142						handle(ex, location, resource);
143					}
144				}
145			}
146			return Collections.unmodifiableMap(result);
147		}
148	
149		private void handle(ConfigDataNotFoundException ex, ConfigDataLocation location,
150				@Nullable ConfigDataResource resource) {
151			if (ex instanceof ConfigDataResourceNotFoundException notFoundException) {
152				ex = notFoundException.withLocation(location);
153			}
154			getNotFoundAction(location, resource).handle(this.logger, ex);
155		}
156	
157		private ConfigDataNotFoundAction getNotFoundAction(ConfigDataLocation location,
158				@Nullable ConfigDataResource resource) {
159			if (location.isOptional() || (resource != null && resource.isOptional())) {
160				return ConfigDataNotFoundAction.IGNORE;
161			}
162			return this.notFoundAction;
163		}
164	
165		Set<ConfigDataLocation> getLoadedLocations() {
166			return this.loadedLocations;
167		}
168	
169		Set<ConfigDataLocation> getOptionalLocations() {
170			return this.optionalLocations;
171		}
172	
173	}
