52	/**
53	 * Builder for {@link SpringApplication} and {@link ApplicationContext} instances with
54	 * convenient fluent API and context hierarchy support. Simple example of a context
55	 * hierarchy:
56	 *
57	 * <pre class="code">
58	 * new SpringApplicationBuilder(ParentConfig.class).child(ChildConfig.class).run(args);
59	 * </pre>
60	 *
61	 * Another common use case is setting active profiles and default properties to set up the
62	 * environment for an application:
63	 *
64	 * <pre class="code">
65	 * new SpringApplicationBuilder(Application.class).profiles(&quot;server&quot;)
66	 * 		.properties(&quot;transport=local&quot;).run(args);
67	 * </pre>
68	 *
69	 * <p>
70	 * If your needs are simpler, consider using the static convenience methods in
71	 * SpringApplication instead.
72	 *
73	 * @author Dave Syer
74	 * @author Andy Wilkinson
75	 * @since 1.0.0
76	 * @see SpringApplication
77	 */
78	public class SpringApplicationBuilder {
79	
80		private final SpringApplication application;
81	
82		private volatile @Nullable ConfigurableApplicationContext context;
83	
84		private @Nullable SpringApplicationBuilder parent;
85	
86		private final AtomicBoolean running = new AtomicBoolean();
87	
88		private final Set<Class<?>> sources = new LinkedHashSet<>();
89	
90		private final Map<String, Object> defaultProperties = new LinkedHashMap<>();
91	
92		private @Nullable ConfigurableEnvironment environment;
93	
94		private Set<String> additionalProfiles = new LinkedHashSet<>();
95	
96		private boolean registerShutdownHookApplied;
97	
98		private boolean configuredAsChild;
99	
100		public SpringApplicationBuilder(Class<?>... sources) {
101			this(null, sources);
102		}
103	
104		public SpringApplicationBuilder(@Nullable ResourceLoader resourceLoader, Class<?>... sources) {
105			this.application = createSpringApplication(resourceLoader, sources);
106		}
107	
108		/**
109		 * Creates a new {@link SpringApplication} instance from the given sources using the
110		 * given {@link ResourceLoader}. Subclasses may override in order to provide a custom
111		 * subclass of {@link SpringApplication}.
112		 * @param resourceLoader the resource loader or {@code null}
113		 * @param sources the sources
114		 * @return the {@link SpringApplication} instance
115		 * @since 2.6.0
116		 */
117		protected SpringApplication createSpringApplication(@Nullable ResourceLoader resourceLoader, Class<?>... sources) {
118			return new SpringApplication(resourceLoader, sources);
119		}
120	
121		/**
122		 * Accessor for the current application context.
123		 * @return the current application context (or {@code null} if not yet running)
124		 */
125		public @Nullable ConfigurableApplicationContext context() {
126			return this.context;
127		}
128	
129		/**
130		 * Accessor for the current application.
131		 * @return the current application (never null)
132		 */
133		public SpringApplication application() {
134			return this.application;
135		}
136	
137		/**
138		 * Create an application context (and its parent if specified) with the command line
139		 * args provided. The parent is run first with the same arguments if it has not yet
140		 * been started.
141		 * @param args the command line arguments
142		 * @return an application context created from the current state
143		 */
144		public ConfigurableApplicationContext run(String... args) {
145			if (this.running.get()) {
146				ConfigurableApplicationContext context = this.context;
147				Assert.state(context != null, "No context set");
148				// If already created we just return the existing context
149				return context;
150			}
151			configureAsChildIfNecessary(args);
152			if (this.running.compareAndSet(false, true)) {
153				// If not already running copy the sources over and then run.
154				this.context = build().run(args);
155			}
156			ConfigurableApplicationContext context = this.context;
157			Assert.state(context != null, "No context set");
158			return context;
159		}
160	
161		private void configureAsChildIfNecessary(String... args) {
162			if (this.parent != null && !this.configuredAsChild) {
163				this.configuredAsChild = true;
164				if (!this.registerShutdownHookApplied) {
165					this.application.setRegisterShutdownHook(false);
166				}
167				initializers(new ParentContextApplicationContextInitializer(this.parent.run(args)));
168			}
169		}
170	
171		/**
172		 * Returns a fully configured {@link SpringApplication} that is ready to run.
173		 * @return the fully configured {@link SpringApplication}.
174		 */
175		public SpringApplication build() {
176			return build(new String[0]);
177		}
178	
179		/**
180		 * Returns a fully configured {@link SpringApplication} that is ready to run. Any
181		 * parent that has been configured will be run with the given {@code args}.
182		 * @param args the parent's args
183		 * @return the fully configured {@link SpringApplication}.
184		 */
185		public SpringApplication build(String... args) {
186			configureAsChildIfNecessary(args);
187			this.application.addPrimarySources(this.sources);
188			return this.application;
189		}
190	
191		/**
192		 * Create a child application with the provided sources. Default args and environment
193		 * are copied down into the child, but everything else is a clean sheet.
194		 * @param sources the sources for the application (Spring configuration)
195		 * @return the child application builder
196		 */
197		public SpringApplicationBuilder child(Class<?>... sources) {
198			SpringApplicationBuilder child = new SpringApplicationBuilder();
199			child.sources(sources);
200	
201			// Copy environment stuff from parent to child
202			child.properties(this.defaultProperties)
203				.environment(this.environment)
204				.additionalProfiles(this.additionalProfiles);
205			child.parent = this;
206	
207			// It's not possible if embedded web server are enabled to support web contexts as
208			// parents because the servlets cannot be initialized at the right point in
209			// lifecycle.
210			web(WebApplicationType.NONE);
211	
212			// Probably not interested in multiple banners
213			bannerMode(Banner.Mode.OFF);
214	
215			// Make sure sources get copied over
216			this.application.addPrimarySources(this.sources);
217	
218			return child;
219		}
220	
221		/**
222		 * Add a parent application with the provided sources. Default args and environment
223		 * are copied up into the parent, but everything else is a clean sheet.
224		 * @param sources the sources for the application (Spring configuration)
225		 * @return the parent builder
226		 */
227		public SpringApplicationBuilder parent(Class<?>... sources) {
228			if (this.parent == null) {
229				this.parent = new SpringApplicationBuilder(sources).web(WebApplicationType.NONE)
230					.properties(this.defaultProperties)
231					.environment(this.environment);
232			}
233			else {
234				this.parent.sources(sources);
235			}
236			return this.parent;
237		}
238	
239		private SpringApplicationBuilder runAndExtractParent(String... args) {
240			if (this.context == null) {
241				run(args);
242			}
243			if (this.parent != null) {
244				return this.parent;
245			}
246			throw new IllegalStateException(
247					"No parent defined yet (please use the other overloaded parent methods to set one)");
248		}
249	
250		/**
251		 * Add an already running parent context to an existing application.
252		 * @param parent the parent context
253		 * @return the current builder (not the parent)
254		 */
255		public SpringApplicationBuilder parent(ConfigurableApplicationContext parent) {
256			this.parent = new SpringApplicationBuilder();
257			this.parent.context = parent;
258			this.parent.running.set(true);
259			return this;
260		}
261	
262		/**
263		 * Create a sibling application (one with the same parent). A side effect of calling
264		 * this method is that the current application (and its parent) are started without
265		 * any arguments if they are not already running. To supply arguments when starting
266		 * the current application and its parent use {@link #sibling(Class[], String...)}
267		 * instead.
268		 * @param sources the sources for the application (Spring configuration)
269		 * @return the new sibling builder
270		 */
271		public SpringApplicationBuilder sibling(Class<?>... sources) {
272			return runAndExtractParent().child(sources);
273		}
274	
275		/**
276		 * Create a sibling application (one with the same parent). A side effect of calling
277		 * this method is that the current application (and its parent) are started if they
278		 * are not already running.
279		 * @param sources the sources for the application (Spring configuration)
280		 * @param args the command line arguments to use when starting the current app and its
281		 * parent
282		 * @return the new sibling builder
283		 */
284		public SpringApplicationBuilder sibling(Class<?>[] sources, String... args) {
285			return runAndExtractParent(args).child(sources);
286		}
287	
288		/**
289		 * Explicitly set the factory used to create the application context.
290		 * @param factory the factory to use
291		 * @return the current builder
292		 * @since 2.4.0
293		 */
294		public SpringApplicationBuilder contextFactory(ApplicationContextFactory factory) {
295			this.application.setApplicationContextFactory(factory);
296			return this;
297		}
298	
299		/**
300		 * Add more sources (configuration classes and components) to this application.
301		 * @param sources the sources to add
302		 * @return the current builder
303		 */
304		public SpringApplicationBuilder sources(Class<?>... sources) {
305			this.sources.addAll(new LinkedHashSet<>(Arrays.asList(sources)));
306			return this;
307		}
308	
309		/**
310		 * Flag to explicitly request a specific type of web application. Auto-detected based
311		 * on the classpath if not set.
312		 * @param webApplicationType the type of web application
313		 * @return the current builder
314		 * @since 2.0.0
315		 */
316		public SpringApplicationBuilder web(WebApplicationType webApplicationType) {
317			this.application.setWebApplicationType(webApplicationType);
318			return this;
319		}
320	
321		/**
322		 * Flag to indicate the startup information should be logged.
323		 * @param logStartupInfo the flag to set. Default true.
324		 * @return the current builder
325		 */
326		public SpringApplicationBuilder logStartupInfo(boolean logStartupInfo) {
327			this.application.setLogStartupInfo(logStartupInfo);
328			return this;
329		}
330	
331		/**
332		 * Sets the {@link Banner} instance which will be used to print the banner when no
333		 * static banner file is provided.
334		 * @param banner the banner to use
335		 * @return the current builder
336		 */
337		public SpringApplicationBuilder banner(Banner banner) {
338			this.application.setBanner(banner);
339			return this;
340		}
341	
342		public SpringApplicationBuilder bannerMode(Banner.Mode bannerMode) {
343			this.application.setBannerMode(bannerMode);
344			return this;
345		}
346	
347		/**
348		 * Sets if the application is headless and should not instantiate AWT. Defaults to
349		 * {@code true} to prevent java icons appearing.
350		 * @param headless if the application is headless
351		 * @return the current builder
352		 */
353		public SpringApplicationBuilder headless(boolean headless) {
354			this.application.setHeadless(headless);
355			return this;
356		}
357	
358		/**
359		 * Sets if the created {@link ApplicationContext} should have a shutdown hook
360		 * registered.
361		 * @param registerShutdownHook if the shutdown hook should be registered
362		 * @return the current builder
363		 */
364		public SpringApplicationBuilder registerShutdownHook(boolean registerShutdownHook) {
365			this.registerShutdownHookApplied = true;
366			this.application.setRegisterShutdownHook(registerShutdownHook);
367			return this;
368		}
369	
370		/**
371		 * Fixes the main application class that is used to anchor the startup messages.
372		 * @param mainApplicationClass the class to use.
373		 * @return the current builder
374		 */
375		public SpringApplicationBuilder main(Class<?> mainApplicationClass) {
376			this.application.setMainApplicationClass(mainApplicationClass);
377			return this;
378		}
379	
380		/**
381		 * Flag to indicate that command line arguments should be added to the environment.
382		 * @param addCommandLineProperties the flag to set. Default true.
383		 * @return the current builder
384		 */
385		public SpringApplicationBuilder addCommandLineProperties(boolean addCommandLineProperties) {
386			this.application.setAddCommandLineProperties(addCommandLineProperties);
387			return this;
388		}
389	
390		/**
391		 * Flag to indicate if the {@link ApplicationConversionService} should be added to the
392		 * application context's {@link Environment}.
393		 * @param addConversionService if the conversion service should be added.
394		 * @return the current builder
395		 * @since 2.1.0
396		 */
397		public SpringApplicationBuilder setAddConversionService(boolean addConversionService) {
398			this.application.setAddConversionService(addConversionService);
399			return this;
400		}
401	
402		/**
403		 * Adds {@link BootstrapRegistryInitializer} instances that can be used to initialize
404		 * the {@link BootstrapRegistry}.
405		 * @param bootstrapRegistryInitializer the bootstrap registry initializer to add
406		 * @return the current builder
407		 * @since 2.4.5
408		 */
409		public SpringApplicationBuilder addBootstrapRegistryInitializer(
410				BootstrapRegistryInitializer bootstrapRegistryInitializer) {
411			this.application.addBootstrapRegistryInitializer(bootstrapRegistryInitializer);
412			return this;
413		}
414	
415		/**
416		 * Flag to control whether the application should be initialized lazily.
417		 * @param lazyInitialization the flag to set. Defaults to false.
418		 * @return the current builder
419		 * @since 2.2
420		 */
421		public SpringApplicationBuilder lazyInitialization(boolean lazyInitialization) {
422			this.application.setLazyInitialization(lazyInitialization);
423			return this;
424		}
425	
426		/**
427		 * Default properties for the environment in the form {@code key=value} or
428		 * {@code key:value}. Multiple calls to this method are cumulative and will not clear
429		 * any previously set properties.
430		 * @param defaultProperties the properties to set.
431		 * @return the current builder
432		 * @see SpringApplicationBuilder#properties(Properties)
433		 * @see SpringApplicationBuilder#properties(Map)
434		 */
435		public SpringApplicationBuilder properties(String... defaultProperties) {
436			return properties(getMapFromKeyValuePairs(defaultProperties));
437		}
438	
439		private Map<String, Object> getMapFromKeyValuePairs(String[] properties) {
440			Map<String, Object> map = new HashMap<>();
441			for (String property : properties) {
442				int index = lowestIndexOf(property, ":", "=");
443				String key = (index > 0) ? property.substring(0, index) : property;
444				String value = (index > 0) ? property.substring(index + 1) : "";
445				map.put(key, value);
446			}
447			return map;
448		}
449	
450		private int lowestIndexOf(String property, String... candidates) {
451			int index = -1;
452			for (String candidate : candidates) {
453				int candidateIndex = property.indexOf(candidate);
454				if (candidateIndex > 0) {
455					index = (index != -1) ? Math.min(index, candidateIndex) : candidateIndex;
456				}
457			}
458			return index;
459		}
460	
461		/**
462		 * Default properties for the environment.Multiple calls to this method are cumulative
463		 * and will not clear any previously set properties.
464		 * @param defaultProperties the properties to set.
465		 * @return the current builder
466		 * @see SpringApplicationBuilder#properties(String...)
467		 * @see SpringApplicationBuilder#properties(Map)
468		 */
469		public SpringApplicationBuilder properties(Properties defaultProperties) {
470			return properties(getMapFromProperties(defaultProperties));
471		}
472	
473		private Map<String, Object> getMapFromProperties(Properties properties) {
474			Map<String, Object> map = new HashMap<>();
475			for (Object key : Collections.list(properties.propertyNames())) {
476				map.put((String) key, properties.get(key));
477			}
478			return map;
479		}
480	
481		/**
482		 * Default properties for the environment. Multiple calls to this method are
483		 * cumulative and will not clear any previously set properties.
484		 * @param defaults the default properties
485		 * @return the current builder
486		 * @see SpringApplicationBuilder#properties(String...)
487		 * @see SpringApplicationBuilder#properties(Properties)
488		 */
489		public SpringApplicationBuilder properties(Map<String, Object> defaults) {
490			this.defaultProperties.putAll(defaults);
491			this.application.setDefaultProperties(this.defaultProperties);
492			if (this.parent != null) {
493				this.parent.properties(this.defaultProperties);
494				this.parent.environment(this.environment);
495			}
496			return this;
497		}
498	
499		/**
500		 * Add to the active Spring profiles for this app (and its parent and children).
501		 * @param profiles the profiles to add.
502		 * @return the current builder
503		 */
504		public SpringApplicationBuilder profiles(String... profiles) {
505			this.additionalProfiles.addAll(Arrays.asList(profiles));
506			this.application.setAdditionalProfiles(StringUtils.toStringArray(this.additionalProfiles));
507			return this;
508		}
