17	package org.springframework.boot.context.config;
18	
19	import java.io.IOException;
20	import java.util.ArrayList;
21	import java.util.Collections;
22	import java.util.List;
23	
24	import org.apache.commons.logging.Log;
25	import org.jspecify.annotations.Nullable;
26	
27	import org.springframework.boot.bootstrap.BootstrapContext;
28	import org.springframework.boot.bootstrap.BootstrapRegistry;
29	import org.springframework.boot.bootstrap.ConfigurableBootstrapContext;
30	import org.springframework.boot.logging.DeferredLogFactory;
31	import org.springframework.core.ResolvableType;
32	import org.springframework.core.io.support.SpringFactoriesLoader;
33	import org.springframework.core.io.support.SpringFactoriesLoader.ArgumentResolver;
34	import org.springframework.core.log.LogMessage;
35	import org.springframework.util.Assert;
36	
37	/**
38	 * A collection of {@link ConfigDataLoader} instances loaded through
39	 * {@code spring.factories}.
40	 *
41	 * @author Phillip Webb
42	 * @author Madhura Bhave
43	 */
44	class ConfigDataLoaders {
45	
46		private final Log logger;
47	
48		@SuppressWarnings("rawtypes")
49		private final List<ConfigDataLoader> loaders;
50	
51		private final List<Class<?>> resourceTypes;
52	
53		/**
54		 * Create a new {@link ConfigDataLoaders} instance.
55		 * @param logFactory the deferred log factory
56		 * @param bootstrapContext the bootstrap context
57		 * @param springFactoriesLoader the loader to use
58		 */
59		ConfigDataLoaders(DeferredLogFactory logFactory, ConfigurableBootstrapContext bootstrapContext,
60				SpringFactoriesLoader springFactoriesLoader) {
61			this.logger = logFactory.getLog(getClass());
62			ArgumentResolver argumentResolver = ArgumentResolver.of(DeferredLogFactory.class, logFactory);
63			argumentResolver = argumentResolver.and(ConfigurableBootstrapContext.class, bootstrapContext);
64			argumentResolver = argumentResolver.and(BootstrapContext.class, bootstrapContext);
65			argumentResolver = argumentResolver.and(BootstrapRegistry.class, bootstrapContext);
66			argumentResolver = argumentResolver.andSupplied(Log.class, () -> {
67				throw new IllegalArgumentException("Log types cannot be injected, please use DeferredLogFactory");
68			});
69			this.loaders = springFactoriesLoader.load(ConfigDataLoader.class, argumentResolver);
70			this.resourceTypes = getResourceTypes(this.loaders);
71		}
72	
73		@SuppressWarnings("rawtypes")
74		private List<Class<?>> getResourceTypes(List<ConfigDataLoader> loaders) {
75			List<Class<?>> resourceTypes = new ArrayList<>(loaders.size());
76			for (ConfigDataLoader<?> loader : loaders) {
77				resourceTypes.add(getResourceType(loader));
78			}
79			return Collections.unmodifiableList(resourceTypes);
80		}
81	
82		private Class<?> getResourceType(ConfigDataLoader<?> loader) {
83			Class<?> generic = ResolvableType.forClass(loader.getClass()).as(ConfigDataLoader.class).resolveGeneric();
84			Assert.state(generic != null, "'generic' must not be null");
85			return generic;
86		}
87	
88		/**
89		 * Load {@link ConfigData} using the first appropriate {@link ConfigDataLoader}.
90		 * @param <R> the resource type
91		 * @param context the loader context
92		 * @param resource the resource to load
93		 * @return the loaded {@link ConfigData}
94		 * @throws IOException on IO error
95		 */
96		<R extends ConfigDataResource> @Nullable ConfigData load(ConfigDataLoaderContext context, R resource)
97				throws IOException {
98			ConfigDataLoader<R> loader = getLoader(context, resource);
99			this.logger.trace(LogMessage.of(() -> "Loading " + resource + " using loader " + loader.getClass().getName()));
100			return loader.load(context, resource);
101		}
102	
103		@SuppressWarnings("unchecked")
104		private <R extends ConfigDataResource> ConfigDataLoader<R> getLoader(ConfigDataLoaderContext context, R resource) {
105			ConfigDataLoader<R> result = null;
106			for (int i = 0; i < this.loaders.size(); i++) {
107				ConfigDataLoader<R> candidate = this.loaders.get(i);
108				if (this.resourceTypes.get(i).isInstance(resource)) {
109					if (candidate.isLoadable(context, resource)) {
110						if (result != null) {
111							throw new IllegalStateException("Multiple loaders found for resource '" + resource + "' ["
112									+ candidate.getClass().getName() + "," + result.getClass().getName() + "]");
113						}
114						result = candidate;
115					}
116				}
117			}
118			Assert.state(result != null, () -> "No loader found for resource '" + resource + "'");
119			return result;
120		}
121	
122	}
