34		private final ValidationErrors validationErrors;
35	
36		BindValidationException(ValidationErrors validationErrors) {
37			super(getMessage(validationErrors));
38			Assert.notNull(validationErrors, "'validationErrors' must not be null");
39			this.validationErrors = validationErrors;
40		}
