26	
27	import org.springframework.beans.NotReadablePropertyException;
28	import org.springframework.boot.context.properties.bind.AbstractBindHandler;
29	import org.springframework.boot.context.properties.bind.BindContext;
30	import org.springframework.boot.context.properties.bind.BindHandler;
31	import org.springframework.boot.context.properties.bind.Bindable;
32	import org.springframework.boot.context.properties.bind.DataObjectPropertyName;
33	import org.springframework.boot.context.properties.source.ConfigurationProperty;
34	import org.springframework.boot.context.properties.source.ConfigurationPropertyName;
35	import org.springframework.boot.context.properties.source.ConfigurationPropertyName.Form;
36	import org.springframework.core.ResolvableType;
37	import org.springframework.util.ObjectUtils;
38	import org.springframework.validation.AbstractBindingResult;
39	import org.springframework.validation.BeanPropertyBindingResult;
40	import org.springframework.validation.Validator;
41	
42	/**
43	 * {@link BindHandler} to apply {@link Validator Validators} to bound results.
44	 *
45	 * @author Phillip Webb
46	 * @author Madhura Bhave
47	 * @since 2.0.0
48	 */
49	public class ValidationBindHandler extends AbstractBindHandler {
50	
51		private final Validator[] validators;
52	
53		private final Map<ConfigurationPropertyName, ResolvableType> boundTypes = new LinkedHashMap<>();
54	
55		private final Map<ConfigurationPropertyName, Object> boundResults = new LinkedHashMap<>();
56	
57		private final Set<ConfigurationProperty> boundProperties = new LinkedHashSet<>();
58	
59		private @Nullable BindValidationException exception;
60	
61		public ValidationBindHandler(Validator... validators) {
62			this.validators = validators;
63		}
64	
65		public ValidationBindHandler(BindHandler parent, Validator... validators) {
66			super(parent);
67			this.validators = validators;
68		}
69	
70		@Override
71		public <T> @Nullable Bindable<T> onStart(ConfigurationPropertyName name, Bindable<T> target, BindContext context) {
72			this.boundTypes.put(name, target.getType());
73			return super.onStart(name, target, context);
74		}
75	
76		@Override
77		public @Nullable Object onSuccess(ConfigurationPropertyName name, Bindable<?> target, BindContext context,
78				Object result) {
79			this.boundResults.put(name, result);
80			if (context.getConfigurationProperty() != null) {
81				this.boundProperties.add(context.getConfigurationProperty());
82			}
83			return super.onSuccess(name, target, context, result);
84		}
85	
86		@Override
87		public @Nullable Object onFailure(ConfigurationPropertyName name, Bindable<?> target, BindContext context,
88				Exception error) throws Exception {
89			Object result = super.onFailure(name, target, context, error);
90			if (result != null) {
91				clear();
92				this.boundResults.put(name, result);
93			}
94			validate(name, target, context, result);
95			return result;
96		}
97	
98		private void clear() {
99			this.boundTypes.clear();
100			this.boundResults.clear();
101			this.boundProperties.clear();
102			this.exception = null;
103		}
104	
105		@Override
106		public void onFinish(ConfigurationPropertyName name, Bindable<?> target, BindContext context,
107				@Nullable Object result) throws Exception {
108			validate(name, target, context, result);
109			super.onFinish(name, target, context, result);
110		}
111	
112		private void validate(ConfigurationPropertyName name, Bindable<?> target, BindContext context,
113				@Nullable Object result) {
114			if (this.exception == null) {
115				Object validationTarget = getValidationTarget(target, context, result);
116				Class<?> validationType = target.getBoxedType().resolve();
117				if (validationTarget != null && validationType != null) {
118					validateAndPush(name, validationTarget, validationType);
119				}
120			}
121			if (context.getDepth() == 0 && this.exception != null) {
122				throw this.exception;
123			}
124		}
125	
126		private @Nullable Object getValidationTarget(Bindable<?> target, BindContext context, @Nullable Object result) {
127			if (result != null) {
128				return result;
129			}
130			if (context.getDepth() == 0 && target.getValue() != null) {
131				return target.getValue().get();
132			}
133			return null;
134		}
135	
136		private void validateAndPush(ConfigurationPropertyName name, Object target, Class<?> type) {
137			ValidationResult result = null;
138			for (Validator validator : this.validators) {
139				if (validator.supports(type)) {
140					result = (result != null) ? result : new ValidationResult(name, target);
141					validator.validate(target, result);
142				}
143			}
144			if (result != null && result.hasErrors()) {
145				this.exception = new BindValidationException(result.getValidationErrors());
146			}
147		}
148	
149		/**
150		 * {@link AbstractBindingResult} implementation backed by the bound properties.
151		 */
152		private class ValidationResult extends BeanPropertyBindingResult {
153	
154			private final ConfigurationPropertyName name;
155	
156			protected ValidationResult(ConfigurationPropertyName name, Object target) {
157				super(target, "");
158				this.name = name;
159			}
160	
161			@Override
162			public String getObjectName() {
163				return this.name.toString();
164			}
165	
166			@Override
167			public @Nullable Class<?> getFieldType(@Nullable String field) {
168				ResolvableType type = getBoundField(ValidationBindHandler.this.boundTypes, field);
169				Class<?> resolved = (type != null) ? type.resolve() : null;
170				if (resolved != null) {
171					return resolved;
172				}
173				return super.getFieldType(field);
174			}
175	
176			@Override
177			protected @Nullable Object getActualFieldValue(String field) {
178				Object boundField = getBoundField(ValidationBindHandler.this.boundResults, field);
179				if (boundField != null) {
180					return boundField;
181				}
182				try {
183					return super.getActualFieldValue(field);
184				}
185				catch (Exception ex) {
186					if (isPropertyNotReadable(ex)) {
187						return null;
188					}
189					throw ex;
190				}
191			}
192	
193			private boolean isPropertyNotReadable(Throwable ex) {
194				while (ex != null) {
195					if (ex instanceof NotReadablePropertyException) {
196						return true;
197					}
198					ex = ex.getCause();
199				}
200				return false;
201			}
202	
203			private <T> @Nullable T getBoundField(Map<ConfigurationPropertyName, T> boundFields, @Nullable String field) {
204				if (field == null) {
205					return null;
206				}
207				try {
208					ConfigurationPropertyName name = getName(field);
209					T bound = boundFields.get(name);
210					if (bound != null) {
211						return bound;
212					}
213					if (name.hasIndexedElement()) {
214						for (Map.Entry<ConfigurationPropertyName, T> entry : boundFields.entrySet()) {
215							if (isFieldNameMatch(entry.getKey(), name)) {
216								return entry.getValue();
217							}
218						}
219					}
220				}
221				catch (Exception ex) {
222					// Ignore
223				}
224				return null;
225			}
226	
227			private boolean isFieldNameMatch(ConfigurationPropertyName name, ConfigurationPropertyName fieldName) {
228				if (name.getNumberOfElements() != fieldName.getNumberOfElements()) {
229					return false;
230				}
231				for (int i = 0; i < name.getNumberOfElements(); i++) {
232					String element = name.getElement(i, Form.ORIGINAL);
233					String fieldElement = fieldName.getElement(i, Form.ORIGINAL);
234					if (!ObjectUtils.nullSafeEquals(element, fieldElement)) {
235						return false;
236					}
237				}
238				return true;
239			}
240	
241			private ConfigurationPropertyName getName(String field) {
242				return this.name.append(DataObjectPropertyName.toDashedForm(field));
243			}
244	
245			ValidationErrors getValidationErrors() {
246				Set<ConfigurationProperty> boundProperties = ValidationBindHandler.this.boundProperties.stream()
247					.filter((property) -> this.name.isAncestorOf(property.getName()))
248					.collect(Collectors.toCollection(LinkedHashSet::new));
249				return new ValidationErrors(this.name, boundProperties, getAllErrors());
250			}
251	
252		}
253	
254	}
