29	
30	/**
31	 * A {@link ConfigurationPropertySource} backed by a {@link Map} and using standard name
32	 * mapping rules.
33	 *
34	 * @author Phillip Webb
35	 * @author Madhura Bhave
36	 * @since 2.0.0
37	 */
38	public class MapConfigurationPropertySource implements IterableConfigurationPropertySource {
39	
40		private static final PropertyMapper[] DEFAULT_MAPPERS = { DefaultPropertyMapper.INSTANCE };
41	
42		private final Map<String, Object> source;
43	
44		private final IterableConfigurationPropertySource delegate;
45	
46		/**
47		 * Create a new empty {@link MapConfigurationPropertySource} instance.
48		 */
49		public MapConfigurationPropertySource() {
50			this(Collections.emptyMap());
51		}
52	
53		/**
54		 * Create a new {@link MapConfigurationPropertySource} instance with entries copies
55		 * from the specified map.
56		 * @param map the source map
57		 */
58		public MapConfigurationPropertySource(Map<?, ?> map) {
59			this.source = new LinkedHashMap<>();
60			MapPropertySource mapPropertySource = new MapPropertySource("source", this.source);
61			this.delegate = new SpringIterableConfigurationPropertySource(mapPropertySource, false, DEFAULT_MAPPERS);
62			putAll(map);
63		}
64	
65		/**
66		 * Add all entries from the specified map.
67		 * @param map the source map
68		 */
69		public void putAll(Map<?, ?> map) {
70			Assert.notNull(map, "'map' must not be null");
71			assertNotReadOnlySystemAttributesMap(map);
72			map.forEach(this::put);
73		}
74	
75		/**
76		 * Add an individual entry.
77		 * @param name the name
78		 * @param value the value
79		 */
80		public void put(Object name, Object value) {
81			Assert.notNull(name, "'name' must not be null");
82			this.source.put(name.toString(), value);
83		}
84	
85		@Override
86		public Object getUnderlyingSource() {
87			return this.source;
88		}
89	
90		@Override
91		public @Nullable ConfigurationProperty getConfigurationProperty(ConfigurationPropertyName name) {
92			return this.delegate.getConfigurationProperty(name);
93		}
94	
95		@Override
96		public Iterator<ConfigurationPropertyName> iterator() {
97			return this.delegate.iterator();
98		}
99	
100		@Override
101		public Stream<ConfigurationPropertyName> stream() {
102			return this.delegate.stream();
103		}
104	
105		private void assertNotReadOnlySystemAttributesMap(Map<?, ?> map) {
106			try {
107				map.size();
108			}
109			catch (UnsupportedOperationException ex) {
110				throw new IllegalArgumentException("Security restricted maps are not supported", ex);
111			}
112		}
113	
114	}
